unique={a['id']:a for a in checks};lr=[]
for m in le['results']:
 for a in m['checks']:lr.append(dict(candidate=m['id'],id=a['id'],confidence=a['confidence'],inside_hull=a['inside_learned_inlier_hull'],error_rgb_px=a['error_RGB_px'],outside_hull_global_extrapolation_error_rgb_px=a['global_only_extrapolation_error_RGB_px']))
